-- Compare the SOURCE and ISOLATED RESTORE. Returns only an irreversible digest.
-- Preserve table/object owners, explicit GRANTs, RLS policies, definer
-- function owners and function grants. Never print source definitions.
SELECT md5(jsonb_build_object(
 'objects',(SELECT coalesce(jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind::text,r.rolname,c.relrowsecurity,c.relforcerowsecurity) ORDER BY n.nspname,c.relname,c.relkind),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname IN ('public','auth','storage') AND c.relkind IN ('r','p','v','m','S')),
 'table_grants',(SELECT coalesce(jsonb_agg(jsonb_build_array(n.nspname,c.relname,coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) ORDER BY n.nspname,c.relname,coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl) a LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE n.nspname IN ('public','auth','storage') AND c.relkind IN ('r','p','v','m','S')),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_array(n.nspname,c.relname,p.polname,p.polcmd::text,p.polpermissive,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid),(SELECT coalesce(jsonb_agg(coalesce(r2.rolname,'PUBLIC') ORDER BY coalesce(r2.rolname,'PUBLIC')),'[]'::jsonb) FROM unnest(p.polroles) role_id LEFT JOIN pg_roles r2 ON r2.oid=role_id)) ORDER BY n.nspname,c.relname,p.polname),'[]'::jsonb) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','auth','storage')),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),r.rolname,p.prosecdef,md5(pg_get_functiondef(p.oid))) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE n.nspname IN ('public','auth','storage') AND p.prokind IN ('f','p')),
 'function_grants',(SELECT coalesce(jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),coalesce(r.rolname,'PUBLIC')),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(p.proacl) a LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE n.nspname IN ('public','auth','storage') AND p.prokind IN ('f','p')),
 'schema_grants',(SELECT coalesce(jsonb_agg(jsonb_build_array(n.nspname,coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) ORDER BY n.nspname,coalesce(r.rolname,'PUBLIC'),a.privilege_type),'[]'::jsonb) FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) a LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE n.nspname IN ('public','auth','storage'))
)::text) AS security_digest;